import random, subprocess, sys, tempfile
from pathlib import Path
REFERENCE="# External reference: statistics page /practice/28336/\n# Accepted submission: 52734521\n# Source: http://cs101.openjudge.cn/practice/solution/52734521/\n# License: not declared on the submission page; no license is inferred.\n\ns = input().strip()\nstack = []\n\nfor c in s:\n    # 如果栈不为空，且栈顶和当前字符相同，就消除（弹出栈顶）\n    if stack and stack[-1] == c:\n        stack.pop()\n    else:\n        stack.append(c)\n\n# 拼接结果\nres = ''.join(stack)\nprint(res if res else 'Empty')"
SAMPLE='abbaca\n'
EXTRA_CASE='\n'
GENERATOR_NAME='g28336'
def g28336(r):
    return "".join(r.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(r.randint(1, 300))) + "\n"

def run(text):
    with tempfile.TemporaryDirectory(prefix='producecase-') as d:
        p=Path(d)/'main.py'; p.write_text(REFERENCE)
        x=subprocess.run([sys.executable,str(p)],input=text,text=True,capture_output=True,timeout=120)
        if x.returncode: raise SystemExit(x.stderr)
        return x.stdout
def main():
    d=Path('data'); d.mkdir(exist_ok=True)
    cases=[SAMPLE]+([EXTRA_CASE] if EXTRA_CASE else [])+[globals()[GENERATOR_NAME](random.Random(s)) for s in range(1,21)]
    for i,c in enumerate(cases): (d/f'{i}.in').write_text(c); (d/f'{i}.out').write_text(run(c))
if __name__=='__main__': main()
